        'ml' => [
            'title' => 'വി. കൃഷ്ണകുമാർ',
            'summary' => 'സമൂഹങ്ങളോടൊപ്പം പരിസ്ഥിതി സംരക്ഷണത്തിനും പങ്കിട്ട പ്രാദേശിക വിഭവങ്ങളുടെ സംരക്ഷണത്തിനുമായി പ്രവർത്തിച്ച വ്യക്തിയാണ് വി. കൃഷ്ണകുമാർ.',
            'body' => "സമൂഹങ്ങളോടൊപ്പം പരിസ്ഥിതി സംരക്ഷണത്തിനും പങ്കിട്ട പ്രാദേശിക വിഭവങ്ങളുടെ സംരക്ഷണത്തിനുമായി പ്രവർത്തിച്ച വ്യക്തിയാണ് വി. കൃഷ്ണകുമാർ.\n\nമാലിന്യ കുറവ്, ജലസംരക്ഷണം, അയൽപ്രദേശങ്ങളിലെ ഹരിത ഇടങ്ങൾ എന്നിവയുമായി ബന്ധപ്പെട്ട ബോധവൽക്കരണ പരിപാടികളിലും പ്രാദേശിക സംരംഭങ്ങളിലും അദ്ദേഹം പങ്കെടുത്തു. ആശയപരമായ സന്ദേശങ്ങളേക്കാൾ പ്രായോഗിക സമൂഹപ്രവർത്തനത്തിനാണ് അദ്ദേഹം മുൻഗണന നൽകിയത്.\n\nസ്വന്തം സമൂഹത്തിന്റെ ആരോഗ്യവുമായി നേരിട്ടുള്ള ബന്ധം ആളുകൾ കാണുമ്പോഴാണ് പരിസ്ഥിതി ഉത്തരവാദിത്വം ശക്തമാകുന്നതെന്ന ആശയമാണ് അദ്ദേഹത്തിന്റെ സമീപനത്തിന്റെ അടിസ്ഥാനം.",
        ],
    ],

    'farid.khan' => [
        'name' => 'Adv. Farid Khan',
        'tier' => 'distinguished',
        'profession' => 'Minority Welfare, Inter-faith Harmony and Social Justice',
        'portrait' => null,
        'en' => [
            'title' => 'Adv. Farid Khan',
            'summary' => 'Adv. Farid Khan has combined professional legal experience with community and civic engagement. His work has included initiatives concerning access to public services, educational opportunity, minority welfare and constructive dialogue among communities.',
            'body' => "Adv. Farid Khan has combined professional legal experience with community and civic engagement. His work has included initiatives concerning access to public services, educational opportunity, minority welfare and constructive dialogue among communities.\n\nHe has encouraged younger participants to approach social questions through discussion and practical cooperation. His public contribution has included both formal advocacy and quieter community work.\n\nHe regards social harmony as something built through ordinary relationships, dignity and repeated opportunities for people from different backgrounds to work together.",
        ],
        'ml' => [
            'title' => 'അഡ്വ. ഫരീദ് ഖാൻ',
            'summary' => 'പ്രൊഫഷണൽ നിയമാനുഭവവും സമൂഹ-പൗര ഇടപെടലുകളും ചേർന്നതാണ് അഡ്വ. ഫരീദ് ഖാന്റെ പൊതുസംഭാവന. പൊതുസേവനങ്ങളിലേക്കുള്ള പ്രവേശനം, വിദ്യാഭ്യാസാവസരങ്ങൾ, ന്യൂനപക്ഷ ക്ഷേമം, സമൂഹങ്ങൾക്കിടയിലെ സൃഷ്ടിപരമായ സംവാദം എന്നിവയുമായി ബന്ധപ്പെട്ട പ്രവർത്തനങ്ങളിൽ അദ്ദേഹം പങ്കെടുത്തു.',
            'body' => "പ്രൊഫഷണൽ നിയമാനുഭവവും സമൂഹ-പൗര ഇടപെടലുകളും ചേർന്നതാണ് അഡ്വ. ഫരീദ് ഖാന്റെ പൊതുസംഭാവന. പൊതുസേവനങ്ങളിലേക്കുള്ള പ്രവേശനം, വിദ്യാഭ്യാസാവസരങ്ങൾ, ന്യൂനപക്ഷ ക്ഷേമം, സമൂഹങ്ങൾക്കിടയിലെ സൃഷ്ടിപരമായ സംവാദം എന്നിവയുമായി ബന്ധപ്പെട്ട പ്രവർത്തനങ്ങളിൽ അദ്ദേഹം പങ്കെടുത്തു.\n\nസാമൂഹിക വിഷയങ്ങളെ മുൻവിധികളേക്കാൾ സംവാദത്തിലൂടെയും പ്രായോഗിക സഹകരണത്തിലൂടെയും സമീപിക്കാൻ യുവാക്കളെ അദ്ദേഹം പ്രോത്സാഹിപ്പിച്ചു. ഔപചാരിക ഇടപെടലുകൾക്കൊപ്പം ശാന്തമായ സമൂഹപ്രവർത്തനത്തിനും അദ്ദേഹത്തിന്റെ പൊതുജീവിതത്തിൽ സ്ഥാനമുണ്ട്.\n\nസാമൂഹിക സൗഹാർദ്ദം സാധാരണ മനുഷ്യബന്ധങ്ങൾ, മാന്യത, വ്യത്യസ്ത പശ്ചാത്തലങ്ങളിലുള്ളവർക്ക് ഒരുമിച്ച് പ്രവർത്തിക്കാനുള്ള അവസരങ്ങൾ എന്നിവയിലൂടെയാണ് വളരുന്നതെന്ന് അദ്ദേഹം കരുതുന്നു.",
        ],
    ],

